-- Function: public.sp_get_monthly_child_attendance
-- Backup generated on 2026-11-11 09:05:52

CREATE OR REPLACE PROCEDURE public.sp_get_monthly_child_attendance(IN p_tenant_id uuid, IN p_branch_id uuid, IN p_year integer, IN p_month integer, IN p_classroom_id uuid DEFAULT NULL::uuid, INOUT cur refcursor DEFAULT 'cur_monthly_child_attendance'::refcursor)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_start_date date := make_date(p_year, p_month, 1);     v_end_date date := (make_date(p_year, p_month, 1) + interval '1 month - 1 day')::date; BEGIN     OPEN cur FOR     WITH eligible_children AS (         SELECT DISTINCT c.id AS child_id,                c.first_name::VARCHAR(100) AS first_name,                c.last_name::VARCHAR(100) AS last_name,                TRIM(c.first_name || ' ' || COALESCE(c.last_name, ''))::VARCHAR(200) AS full_name,                c.photo_url,                COALESCE(                    c.classroom_id,                    (SELECT ca2.classroom_id FROM child_attendance ca2                      WHERE ca2.child_id = c.id AND ca2.branch_id = p_branch_id AND ca2.classroom_id IS NOT NULL                      ORDER BY ca2.attendance_date DESC LIMIT 1),                    (SELECT e.classroom_id FROM enrollments e                      WHERE e.child_id = c.id AND e.branch_id = p_branch_id AND e.classroom_id IS NOT NULL                      ORDER BY e.created_at DESC LIMIT 1)                ) AS default_classroom_id         FROM children c         WHERE c.tenant_id = p_tenant_id           AND (               c.classroom_id IN (SELECT id FROM classrooms WHERE branch_id = p_branch_id)               OR EXISTS (                   SELECT 1 FROM child_attendance ca                    WHERE ca.child_id = c.id                      AND ca.branch_id = p_branch_id                      AND (p_classroom_id IS NULL OR ca.classroom_id = p_classroom_id)               )               OR EXISTS (                   SELECT 1 FROM enrollments e                    WHERE e.child_id = c.id                      AND e.branch_id = p_branch_id                      AND (p_classroom_id IS NULL OR e.classroom_id = p_classroom_id)               )               OR EXISTS (                   SELECT 1 FROM child_care_plans ccp                    WHERE ccp.child_id = c.id                      AND ccp.branch_id = p_branch_id               )           )     ),     deduped_attendance AS (         SELECT DISTINCT ON (ca.child_id, ca.attendance_date)             ca.id AS attendance_id,             ca.child_id,             ca.branch_id,             ca.classroom_id,             ca.attendance_date,             EXTRACT(DAY FROM ca.attendance_date)::INTEGER AS day_of_month,             ca.status::VARCHAR(50) AS status,             ca.arrival_time,             ca.departure_time,             ca.notes         FROM child_attendance ca         WHERE ca.tenant_id = p_tenant_id           AND ca.branch_id = p_branch_id           AND ca.attendance_date >= v_start_date           AND ca.attendance_date <= v_end_date           AND (p_classroom_id IS NULL OR ca.classroom_id = p_classroom_id)         ORDER BY ca.child_id, ca.attendance_date, ca.updated_at DESC, ca.created_at DESC     )     SELECT          ec.child_id,         ec.first_name,         ec.last_name,         ec.full_name,         ec.photo_url,         COALESCE(da.classroom_id, ec.default_classroom_id) AS classroom_id,         COALESCE(cr.name, 'General')::VARCHAR(150) AS classroom_name,         da.attendance_id,         da.attendance_date,         da.day_of_month,         da.status,         da.arrival_time,         da.departure_time,         da.notes     FROM eligible_children ec     LEFT JOIN deduped_attendance da ON ec.child_id = da.child_id     LEFT JOIN classrooms cr ON cr.id = COALESCE(da.classroom_id, ec.default_classroom_id)     WHERE (p_classroom_id IS NULL OR COALESCE(da.classroom_id, ec.default_classroom_id) = p_classroom_id)     ORDER BY ec.full_name, da.day_of_month NULLS LAST; END; $procedure$ ;
